void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec2 center = vec2(0.5, 0.5);
    vec2 offset = uv - center;
    float angle = 0.5 * iTime;  // rotation speed
    float s = sin(angle);
    float c = cos(angle);
    mat2 rotate = mat2(c, -s,
                       s,  c);
    offset = rotate * offset;
    uv = offset + center;

    float baseScale = 8.0;
    float scaleVariation = 16.0 * sin(iTime * 1.5);
    float scale = baseScale + scaleVariation;


    vec2 pix = floor(uv * scale) / scale;

    vec4 color = texture(iChannel0, pix);

    fragColor = color;
}
